// Genuary 4 - Pixels
// Uses a cellular automata with three possible values. The rules are:
// * Get the diamond neighborhood
// . . O . .
// . O . O .
// O . X . O
// . O . O .
// . . O . .
// * Count the number of values that "beat" the current value (1 beats 0, 2 beats 1, and 0 beats 2)
// * If the number is between a threshold (2 to 5), change it to that value
// * If the cell is surrounded by all cells of its same type, change it to the value - 1 (the value this cell beats)

// Changing the neighborhood rules and the thresholds results in different patterns,
// but most of them tend to oscilate or become static too quick

var cw, ch
var gx, gy, pixelSize
var palettes = [
  ["#ffd166", "#ef476f", "#118ab2"],
  ["#ff4f19", "#15084d", "#5ce6e6"],
  ["#294984", "#6ca0a7", "#ffc789"],
  ["#df5f50", "#5a3034", "#fff1dd"],
  ["#2c2060", "#4bd3e5", "#fffbe6"],
  ["#42382a", "#7f6d55", "#c1a784"],
  ["#264653", "#2a9d8f", "#e9c46a"],
  ["#e9d758", "#297373", "#ff8552"],
]
var palette

var mainGrid = []
var maxVal = 3
function setup() {
  palette = random(palettes)
  palette = shuffle(palette)
  let m = max(windowWidth, windowHeight)
  gx = 120
  gy = 120
  pixelSize = floor(m / gx)
  cw = gx * pixelSize
  ch = gy * pixelSize
  createCanvas(cw, ch)

  mainGrid = new Uint32Array(Math.ceil((gx * gy) / 16))

  // Set all cells to a random between 0 and 3, based on noise
  for (let y = 0; y < gy; y++) {
    for (let x = 0; x < gx; x++) {
      //let v = floor(map(noise(x * 0.1, y * 0.1), 0, 1, 0, maxVal))
			let v = floor(random(maxVal))
      setCellState(mainGrid, x, y, v)
    }
  }
  frameRate(30)
}

function setCellState(grid, x, y, state) {
  let index = Math.floor((y * gx + x) / 16)
  let bitPosition = ((y * gx + x) % 16) * 2
  let mask = 3 << bitPosition // 3 is 0b11 in binary
  grid[index] = (grid[index] & ~mask) | (state << bitPosition)
}

function getCellState(grid, x, y) {
  // Check out of bounds
  if (x < 0 || x >= gx || y < 0 || y >= gy) {
    return -1
  }
  var index = Math.floor((y * gx + x) / 16)
  var bitPosition = ((y * gx + x) % 16) * 2
  return (grid[index] >> bitPosition) & 3 // Extract two bits
}

function draw() {
  background(250)
  noStroke()

  for (let y = 0; y < gy; y++) {
    for (let x = 0; x < gx; x++) {
      let state = getCellState(mainGrid, x, y)
      fill(palette[state])
      rect(x * pixelSize, y * pixelSize, pixelSize, pixelSize)
    }
  }
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    addRandom()
  }
  let grid = updateGrid()
  mainGrid = grid
}

var beats = (v1, v2) => {
  return v1 === (v2 + 1) % maxVal
}

function updateGrid() {
  const newGrid = new Uint32Array(mainGrid)
  for (let y = 0; y < gy; y++) {
    for (let x = 0; x < gx; x++) {
      // Get diamond neighborhood
      let neighborhood = [
        [x, y - 2],
        [x - 1, y - 1],
        [x + 1, y - 1],
        [x - 2, y],
        [x + 2, y],
        [x - 1, y + 1],
        [x + 1, y + 1],
        [x, y + 2]
      ]
      // Get current cell value
      let P = getCellState(mainGrid, x, y)
      let values = neighborhood.map(([x, y]) => getCellState(mainGrid, x, y))
      let V = P

      // Count the number of values that beat current value. If > than threshold, then transform it into the one that beats it
      let threshold = 5
      let lowerThreshold = 2
      let valueCounts = values.filter(v => beats(v, P)).length
      if (valueCounts > lowerThreshold && valueCounts < threshold) {
        V = (P + 1) % maxVal
      }

      // If all neighbors are the same color, then change to to the next value
      let allSame = values.every(v => v === P)
      if (allSame) {
        V = (P + 2) % maxVal
      }

      // Set the new state in the copy of the grid
      setCellState(newGrid, x, y, V)
    }
  }
  return newGrid
}

function addRandom() {
  let x = floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / pixelSize)
  let y = floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / pixelSize)
  var neighborhood = []
  for (let dy = -2; dy <= 2; dy++) {
    for (let dx = -2; dx <= 2; dx++) {
      neighborhood.push([x + dx, y + dy])
    }
  }
  for (let [dx, dy] of neighborhood) {
    setCellState(mainGrid, dx, dy, floor(random(maxVal)))
  }
}

function mouseClicked () {
  randomizePalette()
}

function randomizePalette() {
  palette = random(palettes)
  palette = shuffle(palette)
}
